mapper.select:
SELECT *
FROM stock_watch_price_failure_assessment
WHERE rule_version = #{ruleVersion}
  AND market = #{market}
  AND source_date = #{sourceDate}
  AND source_time_epoch_ms >= #{minimumSourceTimeEpochMs}
  AND source_time_epoch_ms <= #{maximumSourceTimeEpochMs}
  AND available_time_epoch_ms <= #{maximumAvailableTimeEpochMs}
  AND eligible = TRUE
  AND high_position = TRUE
  AND active_turnover = TRUE
  AND current_not_collapsed = TRUE
  AND price_shape_triggered = FALSE
ORDER BY source_time_epoch_ms DESC, id ASC
